/*
 * @param	event RemoveOrdersFromPayoutEvent
 */
@EventHandler( payloadType=RemoveOrdersFromPayoutEvent.class)
public void handle( RemoveOrdersFromPayoutEvent event) {
    LOGGER.info("handling RemoveOrdersFromPayoutEvent - " + event );

    Payout entity = removeFromOrders(event.getPayoutId(), event.getRemoveFrom() );
    
	// ------------------------------------------
	// emit to subscribers that find one
	// ------------------------------------------    	
    emitFindPayout( entity );

	// ------------------------------------------
	// emit to subscribers that find all
	// ------------------------------------------    	
    emitFindAllPayout( entity );
}



    /**
     * Method to retrieve the Payout via an PayoutPrimaryKey.
     * @param 	id Long
     * @return 	Payout
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Payout handle( FindPayoutQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPayoutId() );
    }
    
    /**
     * Method to retrieve a collection of all Payouts
     *
     * @param	query	FindAllPayoutQuery 
     * @return 	List<Payout> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Payout> handle( FindAllPayoutQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPayout,
 * but only if the id matches
 *
 * @param		entity	Payout
 */
	protected void emitFindPayout( Payout entity ) {
		LOGGER.info("handling emitFindPayout" );
		
	    queryUpdateEmitter.emit(FindPayoutQuery.class,
	                            query -> query.getFilter().getPayoutId().equals(entity.getPayoutId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPayout
	 * 
	 * @param		entity	Payout
	 */
	protected void emitFindAllPayout( Payout entity ) {
		LOGGER.info("handling emitFindAllPayout" );
		
	    queryUpdateEmitter.emit(FindAllPayoutQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
